DROP TABLE IF EXISTS parameter_status;
DROP TABLE IF EXISTS scenario_parameter;
DROP TABLE IF EXISTS component_register;
DROP TABLE IF EXISTS component_type;
DROP TABLE IF EXISTS constraint_catalog;
CREATE TABLE component_type(component_type TEXT PRIMARY KEY, description TEXT NOT NULL, typical_failure TEXT NOT NULL);
CREATE TABLE component_register(component_id INTEGER PRIMARY KEY, symbol TEXT NOT NULL, name TEXT NOT NULL, component_type TEXT NOT NULL, role TEXT NOT NULL, unit_or_domain TEXT NOT NULL, source_or_rationale TEXT NOT NULL, review_question TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','review','revise','archive')));
CREATE TABLE scenario_parameter(scenario TEXT PRIMARY KEY, initial_stock REAL NOT NULL CHECK(initial_stock >= 0), capacity REAL NOT NULL CHECK(capacity > 0), inflow REAL NOT NULL CHECK(inflow >= 0), demand REAL NOT NULL CHECK(demand >= 0), loss_rate REAL NOT NULL CHECK(loss_rate >= 0 AND loss_rate <= 1), periods INTEGER NOT NULL CHECK(periods > 0), description TEXT);
CREATE TABLE parameter_status(parameter TEXT PRIMARY KEY, status TEXT NOT NULL, unit_or_domain TEXT NOT NULL, source_or_rationale TEXT NOT NULL, uncertainty_note TEXT NOT NULL, sensitivity_test TEXT NOT NULL);
CREATE TABLE constraint_catalog(constraint_name TEXT PRIMARY KEY, constraint_type TEXT NOT NULL, expression TEXT NOT NULL, meaning TEXT NOT NULL, review_question TEXT NOT NULL);
INSERT INTO component_type VALUES ('state_variable','Carries system condition over time.','State does not preserve what the model must remember.'),('input_variable','External or scenario quantity entering the model.','Input is actually endogenous or adaptive.'),('input_or_decision_variable','Quantity that may be external or controllable.','Role changes without documentation.'),('output_variable','Quantity produced for interpretation.','Output does not answer the intended question.'),('parameter','Value that shapes model behavior.','Parameter is assumed, unstable, or overconfidently interpreted.'),('constraint_parameter','Parameter that also defines a bound.','Capacity or feasibility is misunderstood.');
INSERT INTO component_register(symbol,name,component_type,role,unit_or_domain,source_or_rationale,review_question,status) VALUES ('S_t','storage','state_variable','Tracks stored resource over time','0 <= S_t <= K','Core stock variable for accumulation','Does aggregate storage preserve the needed system state?','active'),('I_t','inflow','input_variable','Adds resource to storage','resource units per period','Scenario or observed inflow','Is inflow observed forecast stochastic or scenario-based?','review'),('D_t','demand','input_or_decision_variable','Removes resource from storage','resource units per period','Scenario demand','Is demand fixed adaptive uncertain or controllable?','review'),('lambda','loss_rate','parameter','Controls proportional losses','0 <= lambda <= 1 per period','Assumed loss-rate parameter','How sensitive are outputs to the loss-rate parameter?','review'),('K','capacity','constraint_parameter','Defines the upper storage bound','resource units','Physical or usable capacity','Is capacity theoretical usable seasonal or policy-defined?','review');
INSERT INTO scenario_parameter VALUES ('baseline',80,100,8,6,0.015,60,'Reference scenario'),('low_inflow',80,100,5,6,0.015,60,'Lower inflow'),('high_demand',80,100,8,8,0.015,60,'Higher demand'),('high_loss_rate',80,100,8,6,0.040,60,'Higher loss'),('tight_capacity',70,75,8,6,0.015,60,'Tighter capacity'),('constraint_stress',40,60,3,7,0.050,60,'Constraint stress');
INSERT INTO parameter_status VALUES ('lambda','assumed','0 <= lambda <= 1 per period','Simplified proportional loss assumption','May vary by season condition or process','Compare baseline and high loss-rate scenarios'),('K','scenario_parameter','resource units','Capacity differs by scenario','Usable capacity may differ from theoretical capacity','Compare baseline and tight capacity');
INSERT INTO constraint_catalog VALUES ('nonnegative_storage','domain','S_t >= 0','Storage cannot be negative.','Does the model track shortage when storage reaches zero?'),('capacity_bound','physical','S_t <= K','Storage cannot exceed capacity.','Is capacity theoretical usable seasonal or policy-defined?'),('loss_rate_domain','domain','0 <= lambda <= 1','Loss rate must be a valid fraction per period.','Is the rate unit consistent with the time step?');
